// Score one dataset row against what MunshiJi actually said. All four metrics are numbers
// because the Evaluation node records numeric metrics; the three booleans go out as 0/1.
const row = $('When fetching a dataset row').first().json;
const turn = $json;

const reply = [turn.reply, turn.reply_display].filter(Boolean).join(' ');
const tools = (turn.tool_calls ?? []).map((call) => call.name);

const toolMatch = tools.includes(row.expected_tool) ? 1 : 0;
const factPresent = row.expected_contains && reply.includes(row.expected_contains) ? 1 : 0;
const languageOk =
  typeof turn.language === 'string' &&
  turn.language.toLowerCase().startsWith(String(row.expected_language || '').toLowerCase())
    ? 1
    : 0;
const latencyMs = turn.meta?.latency_ms ?? 0;

return [{ json: {
  tool_match: toolMatch,
  fact_present: factPresent,
  language_ok: languageOk,
  latency_ms: latencyMs,
  tools_called: tools.join(','),
  reply: turn.reply ?? '',
} }];
